/**
 * Figures for the risk and survival objectives primer
 * (web/content/learn/techniques/risk-survival.mdx).
 *
 * The toy is the two slot machines and a bankroll from the primer. The one
 * Drop7 trace is read from web/content/learn/data/sample-game.json, a single
 * playground game generated by web/scripts/generate-sample-game.ts with the
 * TypeScript engine; it is a teaching device and no research number appears
 * here. Server components: SVG with CSS keyframes in ./risk-survival.css on
 * elements marked data-anim. Every figure is complete at its first frame and
 * rests on a designed frame under prefers-reduced-motion.
 */
import { existsSync, readFileSync } from "node:fs";
import { join } from "node:path";
import type { ReactNode } from "react";
import "./risk-survival.css";

const MONO = "var(--font-mono)";
const SANS = "var(--font-sans)";
const INK = "var(--color-ink)";
const INK1 = "var(--color-ink-1)";
const INK2 = "var(--color-ink-2)";
const INK3 = "var(--color-ink-3)";
const RULE = "var(--color-rule-strong)";
const RAISED = "var(--color-raised)";
const ACCENT = "var(--color-accent)";
const MACHINE_A = "var(--color-series-1)";
const MACHINE_B = "var(--color-series-2)";
const BROKE = "var(--color-series-7)";
const SCORE = "var(--color-series-1)";
const HEIGHT = "var(--color-series-2)";
const RISE = "var(--color-series-3)";

function Fig({ viewBox, label, caption, children }: { viewBox: string; label: string; caption: string; children: ReactNode }) {
  return (
    <figure className="fig primer-risk">
      <div className="fig-frame">
        <svg viewBox={viewBox} role="img" aria-label={label}>
          {children}
        </svg>
      </div>
      <figcaption>{caption}</figcaption>
    </figure>
  );
}

/* =========================================================================
 * 1. Same mean, different tails.
 * ========================================================================= */

/** Toy bankrolls after twenty pulls: machine A nets two coins a pull; machine B swings. */
const BANKROLL_A = [43, 42, 44, 43, 41, 45, 43, 42, 44, 43, 40, 46];
const BANKROLL_B = [0, 0, 0, 0, 0, 0, 14, 22, 31, 39, 48, 57];

export function RiskSameMeanDifferentTails() {
  const x0 = 150;
  const x1 = 500;
  const payX = (v: number) => x0 + (v / 6) * (x1 - x0);
  const bankX = (v: number) => x0 + (v / 60) * (x1 - x0);
  const grid = (n: number, i: number) => ({ dx: (i % 4) * 8 - 12, dy: Math.floor(i / 4) * 8 - (n > 4 ? 4 : 0) });
  // Index of each broke round within the pile at zero, computed once before render.
  const pileIndexB = new Map<number, number>();
  BANKROLL_B.forEach((v, i) => {
    if (v === 0) pileIndexB.set(i, pileIndexB.size);
  });
  return (
    <Fig
      viewBox="0 0 560 262"
      label="Two panels: the payout per pull of two machines with the same mean marker, and their bankrolls after twenty pulls, where one machine's dots pile against a broke line at zero"
      caption="Top: what each pull pays. Machine A pays 3 every time; machine B pays 0 or 6; the mean, marked by the triangle, is 3 for both. Bottom: the bankroll after twenty pulls in a dozen toy rounds each. Machine A's rounds cluster together, and half of machine B's rounds ended against the line at zero, where the player is out and the sixes that were coming never arrived."
    >
      <text x={12} y={22} fontFamily={MONO} fontSize={10} fill={INK3}>
        payout per pull
      </text>
      <text x={12} y={56} fontFamily={SANS} fontSize={11} fill={INK1}>
        machine A
      </text>
      <text x={12} y={84} fontFamily={SANS} fontSize={11} fill={INK1}>
        machine B
      </text>
      {Array.from({ length: 8 }, (_, i) => {
        const g = grid(8, i);
        return <circle key={`a${i}`} cx={payX(3) + g.dx} cy={52 + g.dy} r={3.4} fill={MACHINE_A} />;
      })}
      {Array.from({ length: 4 }, (_, i) => (
        <circle key={`b0${i}`} cx={payX(0) + 4 + (i % 2) * 8} cy={76 + Math.floor(i / 2) * 8} r={3.4} fill={MACHINE_B} />
      ))}
      {Array.from({ length: 4 }, (_, i) => (
        <circle key={`b6${i}`} cx={payX(6) - 4 - (i % 2) * 8} cy={76 + Math.floor(i / 2) * 8} r={3.4} fill={MACHINE_B} />
      ))}
      <line x1={x0} y1={100} x2={x1} y2={100} stroke={RULE} />
      {[0, 3, 6].map((v) => (
        <g key={v}>
          <line x1={payX(v)} y1={100} x2={payX(v)} y2={104} stroke={INK3} />
          <text x={payX(v)} y={116} textAnchor="middle" fontFamily={MONO} fontSize={9} fill={INK3}>
            {v}
          </text>
        </g>
      ))}
      <line x1={payX(3)} y1={40} x2={payX(3)} y2={100} stroke={INK2} strokeDasharray="3 3" />
      <path d={`M${payX(3) - 5} 106l5-6 5 6z`} fill={INK} />
      <text x={payX(3) + 10} y={116} fontFamily={MONO} fontSize={9} fill={INK}>
        mean 3, both machines
      </text>

      <text x={12} y={150} fontFamily={MONO} fontSize={10} fill={INK3}>
        bankroll after 20 pulls, twelve rounds each
      </text>
      <text x={12} y={184} fontFamily={SANS} fontSize={11} fill={INK1}>
        machine A
      </text>
      <text x={12} y={216} fontFamily={SANS} fontSize={11} fill={INK1}>
        machine B
      </text>
      <line x1={bankX(0)} y1={158} x2={bankX(0)} y2={236} stroke={BROKE} strokeWidth={2} />
      <text x={bankX(0)} y={152} textAnchor="middle" fontFamily={MONO} fontSize={9.5} fill={BROKE}>
        broke
      </text>
      {BANKROLL_A.map((v, i) => (
        <circle key={`ba${i}`} cx={bankX(v)} cy={180 + ((i % 3) - 1) * 6} r={3.4} fill={MACHINE_A} />
      ))}
      {BANKROLL_B.map((v, i) => {
        if (v === 0) {
          const k = pileIndexB.get(i) ?? 0;
          return <circle key={`bb${i}`} cx={bankX(0) + 6 + (k % 2) * 8} cy={204 + Math.floor(k / 2) * 8} r={3.4} fill={MACHINE_B} />;
        }
        return <circle key={`bb${i}`} cx={bankX(v)} cy={212 + ((i % 2) - 0.5) * 6} r={3.4} fill={MACHINE_B} />;
      })}
      <line x1={x0} y1={236} x2={x1} y2={236} stroke={RULE} />
      {[0, 30, 60].map((v) => (
        <g key={v}>
          <line x1={bankX(v)} y1={236} x2={bankX(v)} y2={240} stroke={INK3} />
          <text x={bankX(v)} y={252} textAnchor="middle" fontFamily={MONO} fontSize={9} fill={INK3}>
            {v}
          </text>
        </g>
      ))}
      <text x={x1} y={252} textAnchor="end" fontFamily={MONO} fontSize={9} fill={INK3}>
        coins
      </text>
    </Fig>
  );
}

/* =========================================================================
 * 2. The blend dial: from the mean to the worst case, the choice flips.
 * ========================================================================= */

export function RiskBlendDial() {
  const trackX0 = 110;
  const trackX1 = 470;
  const barX = 110;
  const barW = 300;
  return (
    <Fig
      viewBox="0 0 560 214"
      label="Two bars for machines A and B above a slider that runs from mean to worst case; as the knob moves right, B's bar shrinks and the chosen machine flips from a tie to A"
      caption="One dial sets how much of the objective is the mean and how much is the worst case. At the mean end the two machines tie, because both pay 3 on average. As the dial moves toward the worst case, machine B's value falls toward its worst pull, which pays nothing, and machine A is chosen. The knob travels the dial and returns; under reduced motion it rests at the worst-case end."
    >
      <text x={12} y={22} fontFamily={MONO} fontSize={10} fill={INK3}>
        value of each machine under the blended objective
      </text>
      <text x={12} y={62} fontFamily={SANS} fontSize={11} fill={INK1}>
        machine A
      </text>
      <rect x={barX} y={50} width={barW} height={16} rx={4} fill={MACHINE_A} />
      <text x={12} y={98} fontFamily={SANS} fontSize={11} fill={INK1}>
        machine B
      </text>
      <rect x={barX} y={86} width={barW} height={16} rx={4} fill={RAISED} stroke={RULE} />
      <rect x={barX} y={86} width={barW} height={16} rx={4} fill={MACHINE_B} data-anim="bar-b" />

      <g transform="translate(436 78)">
        <g data-anim="tie">
          <rect width={100} height={24} rx={12} fill={RAISED} stroke={INK3} />
          <text x={50} y={16} textAnchor="middle" fontFamily={MONO} fontSize={10} fill={INK2}>
            a tie
          </text>
        </g>
        <g data-anim="a-wins" opacity={0}>
          <rect width={100} height={24} rx={12} fill={RAISED} stroke={MACHINE_A} />
          <text x={50} y={16} textAnchor="middle" fontFamily={MONO} fontSize={10} fill={MACHINE_A}>
            A is chosen
          </text>
        </g>
      </g>

      <line x1={trackX0} y1={150} x2={trackX1} y2={150} stroke={RULE} strokeWidth={4} strokeLinecap="round" />
      <text x={trackX0} y={176} textAnchor="middle" fontFamily={MONO} fontSize={10} fill={INK2}>
        mean
      </text>
      <text x={trackX1} y={176} textAnchor="middle" fontFamily={MONO} fontSize={10} fill={INK2}>
        worst case
      </text>
      <g transform={`translate(${trackX0} 150)`}>
        <g data-anim="knob">
          <circle r={9} fill={ACCENT} />
        </g>
      </g>
      <text x={290} y={202} textAnchor="middle" fontFamily={MONO} fontSize={9.5} fill={INK3}>
        value = (1 − d) × mean + d × worst case, for a dial position d from 0 to 1
      </text>
    </Fig>
  );
}

/* =========================================================================
 * 3. The staircase: one playground game's score and tallest column, move by move.
 * ========================================================================= */

interface SampleGame {
  seedHex: string;
  policy: { name: string; rule: string };
  summary: { moves: number; score: number; rises: number; ending: string };
  history: { move: number; score: number; maxHeight: number; rise: boolean }[];
}

function loadSampleGame(): SampleGame | null {
  const path = join(process.cwd(), "content", "learn", "data", "sample-game.json");
  if (!existsSync(path)) return null;
  return JSON.parse(readFileSync(path, "utf8")) as SampleGame;
}

export function RiskStaircase() {
  const game = loadSampleGame();
  if (!game) {
    return (
      <figure className="fig primer-risk">
        <div className="fig-frame">
          <p style={{ color: INK3, fontSize: 13, margin: "1rem" }}>
            The sample game is not available in this checkout. Run <code>npm run figures:sample-game</code> inside <code>web/</code> to
            regenerate <code>content/learn/data/sample-game.json</code>.
          </p>
        </div>
      </figure>
    );
  }
  const moves = game.history.length;
  const plotX0 = 64;
  const plotX1 = 496;
  const plotY0 = 34;
  const plotY1 = 208;
  const scoreTop = Math.max(1, Math.ceil(game.summary.score / 20000)) * 20000;
  const mx = (m: number) => plotX0 + (m / moves) * (plotX1 - plotX0);
  const sy = (v: number) => plotY1 - (v / scoreTop) * (plotY1 - plotY0);
  const hy = (h: number) => plotY1 - (h / 7) * (plotY1 - plotY0);
  const scorePoints: string[] = [`${mx(0)},${sy(0)}`];
  const heightPoints: string[] = [`${mx(0)},${hy(0)}`];
  let prevScore = 0;
  let prevHeight = 0;
  for (const step of game.history) {
    scorePoints.push(`${mx(step.move)},${sy(prevScore)}`, `${mx(step.move)},${sy(step.score)}`);
    heightPoints.push(`${mx(step.move)},${hy(prevHeight)}`, `${mx(step.move)},${hy(step.maxHeight)}`);
    prevScore = step.score;
    prevHeight = step.maxHeight;
  }
  const ending = game.summary.ending === "no-room-to-rise" ? "no room to rise" : game.summary.ending;
  return (
    <Fig
      viewBox="0 0 560 250"
      label="A staircase of score rising at every fifth move beside a line for the tallest column that ratchets up until it reaches the top of the board"
      caption={`One complete playground game (seed ${game.seedHex}, played by the toy rule "${game.policy.rule}"), generated by web/scripts/generate-sample-game.ts with the TypeScript engine. The score climbs by 17,000 at each rise, marked below the axis, and is nearly flat between. The tallest column ratchets up at the same moments until the board has no room left. The game ended after ${game.summary.moves} moves: ${ending}. One toy game is not evidence about anything except what a game looks like.`}
    >
      <text x={12} y={20} fontFamily={MONO} fontSize={10} fill={INK3}>
        {`one game, ${game.summary.moves} moves, ${game.summary.rises} rises`}
      </text>
      <g transform="translate(330 8)">
        <rect width={14} height={4} y={6} rx={2} fill={SCORE} />
        <text x={20} y={13} fontFamily={MONO} fontSize={9.5} fill={INK2}>
          score
        </text>
        <rect x={74} width={14} height={4} y={6} rx={2} fill={HEIGHT} />
        <text x={94} y={13} fontFamily={MONO} fontSize={9.5} fill={INK2}>
          tallest column
        </text>
      </g>

      <line x1={plotX0} y1={plotY1} x2={plotX1} y2={plotY1} stroke={RULE} />
      <line x1={plotX0} y1={plotY0} x2={plotX0} y2={plotY1} stroke={RULE} />
      <line x1={plotX1} y1={plotY0} x2={plotX1} y2={plotY1} stroke={RULE} />
      <line x1={plotX0} y1={hy(7)} x2={plotX1} y2={hy(7)} stroke={HEIGHT} strokeDasharray="3 4" opacity={0.6} />
      <text x={plotX1 - 4} y={hy(7) - 4} textAnchor="end" fontFamily={MONO} fontSize={9} fill={HEIGHT}>
        top of the board
      </text>

      <text x={plotX0 - 6} y={plotY1 + 3} textAnchor="end" fontFamily={MONO} fontSize={9} fill={INK3}>
        0
      </text>
      <text x={plotX0 - 6} y={plotY0 + 3} textAnchor="end" fontFamily={MONO} fontSize={9} fill={INK3}>
        {scoreTop.toLocaleString("en-US")}
      </text>
      <text x={plotX1 + 6} y={plotY1 + 3} fontFamily={MONO} fontSize={9} fill={INK3}>
        0
      </text>
      <text x={plotX1 + 6} y={plotY0 + 3} fontFamily={MONO} fontSize={9} fill={INK3}>
        7 rows
      </text>

      {game.history
        .filter((step) => step.rise)
        .map((step) => (
          <g key={step.move}>
            <line x1={mx(step.move)} y1={plotY1} x2={mx(step.move)} y2={plotY1 + 6} stroke={RISE} strokeWidth={2} />
          </g>
        ))}
      <text x={plotX0} y={plotY1 + 20} fontFamily={MONO} fontSize={9} fill={RISE}>
        rise: +17,000
      </text>
      <text x={(plotX0 + plotX1) / 2} y={plotY1 + 34} textAnchor="middle" fontFamily={MONO} fontSize={9} fill={INK3}>
        {`moves 1 to ${moves}`}
      </text>

      <polyline points={heightPoints.join(" ")} fill="none" stroke={HEIGHT} strokeWidth={1.6} />
      <polyline points={scorePoints.join(" ")} fill="none" stroke={SCORE} strokeWidth={2} />
      <path d={`M${mx(moves) - 4} ${sy(prevScore) - 4}l8 8M${mx(moves) + 4} ${sy(prevScore) - 4}l-8 8`} stroke={BROKE} strokeWidth={1.8} />
    </Fig>
  );
}
